-- Generated by controller/gear_sets.py: Season 8 PvP gear per bot class/spec
DROP TABLE IF EXISTS `botarena_gear`;
CREATE TABLE `botarena_gear` (`class` TINYINT UNSIGNED NOT NULL, `spec` TINYINT UNSIGNED NOT NULL, `slot` TINYINT UNSIGNED NOT NULL, `item` INT UNSIGNED NOT NULL, `enchant` INT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY (`class`,`spec`,`slot`)) ENGINE=InnoDB;
DROP TABLE IF EXISTS `botarena_gear_gems`;
CREATE TABLE `botarena_gear_gems` (`class` TINYINT UNSIGNED NOT NULL, `spec` TINYINT UNSIGNED NOT NULL, `gem_red` INT UNSIGNED NOT NULL, `gem_yellow` INT UNSIGNED NOT NULL, `gem_blue` INT UNSIGNED NOT NULL, `gem_meta` INT UNSIGNED NOT NULL, PRIMARY KEY (`class`,`spec`)) ENGINE=InnoDB;
